<h1>Cadastro de produtos</h1><section class="panel"><h2><?= $edit ? 'Editar produto' : 'Novo produto' ?></h2><form method="post" action="?pagina=produtos&acao=salvar" class="grid"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><label>Nome *<input name="nome" required value="<?= e($edit['nome'] ?? '') ?>"></label><label>Descrição<input name="descricao" value="<?= e($edit['descricao'] ?? '') ?>"></label><label>Preço (R$) *<input type="number" name="preco" min="0.01" step="0.01" required value="<?= e($edit['preco'] ?? '') ?>"></label><label>Estoque *<input type="number" name="estoque" min="0" value="<?= e($edit['estoque'] ?? 0) ?>" required></label><button>Salvar produto</button><?php if($edit): ?><a href="?pagina=produtos">Cancelar</a><?php endif; ?></form></section>
<section class="panel"><h2>Produtos disponíveis</h2><div class="table-wrap"><table><tr><th>Produto</th><th>Preço</th><th>Estoque</th><th>Ação</th></tr><?php foreach($produtos as $p): ?><tr><td><?= e($p['nome']) ?></td><td><?= money($p['preco']) ?></td><td><?= (int)$p['estoque'] ?></td><td><a href="?pagina=produtos&editar=<?= (int)$p['id'] ?>">Editar</a> <form method="post" action="?pagina=produtos&acao=excluir" onsubmit="return confirm('Remover produto?')"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="danger">Remover</button></form></td></tr><?php endforeach; ?></table></div></section>
